  color: var(--navy,#172f36);
  transform: rotate(-5deg);
  box-shadow: 0 10px 24px #172f3612;
  font-size: 0.83rem;
  line-height: 1.5;
  animation: ds-tag-settle 900ms var(--ease,cubic-bezier(0.16, 1, 0.3, 1)) both; }
.ds-tag::after { content: "";
